command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$revision="9700082da4a2071274e34c2fad4200c4fb71e226"
$temp=Join-Path $env:RUNNER_TEMP "fly-git-evidence-storage-contract-9700082"
if(Test-Path -LiteralPath $temp){throw "Candidate worktree already exists"}
Set-Location -LiteralPath $repo
& git fetch origin main --no-tags
if($LASTEXITCODE -ne 0){throw "Main fetch failed"}
$observed=(& git rev-parse refs/remotes/origin/main).Trim()
if($LASTEXITCODE -ne 0 -or $observed -ne $revision){throw "Main SHA moved"}
try {
  & git worktree add --detach $temp $revision
  if($LASTEXITCODE -ne 0){throw "Candidate worktree creation failed"}
  Set-Location -LiteralPath $temp
  & python -X utf8 -m unittest tests/winui/test_remote_evidence_archive_contract.py tests/winui/test_remote_windows_task_contract.py tests/winui/test_validation_scope_contract.py
  if($LASTEXITCODE -ne 0){throw "REPOSITORY_EVIDENCE_CONTRACT_FAILURE"}
  Write-Host "REPOSITORY_EVIDENCE_CONTRACT=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){
    & git worktree remove --force $temp
    if($LASTEXITCODE -ne 0){Write-Host "REPOSITORY_EVIDENCE_CLEANUP=FAIL"}
  }
  & git worktree prune
}
